using System;using System.IO;using System.Linq;using UnityEngine;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;using UnityEngine.Rendering.Universal;using Newtonsoft.Json.Linq;
public static class RemainingCapture {
 static string Repo=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string O=>Repo+"/Docs/검수/2026-11-08_B5_RemainingDomes/";
 static void Shot(string name,Vector3 pos,Vector3 target,float fov=85){var go=new GameObject("Remaining_Review_Temporary");var c=go.AddComponent<Camera>();c.transform.position=pos;c.transform.LookAt(target);c.nearClipPlane=.03f;c.farClipPlane=200;c.fieldOfView=fov;c.GetUniversalAdditionalCameraData().renderPostProcessing=false;var rt=new RenderTexture(1600,1000,24){antiAliasing=4};var prev=RenderTexture.active;Texture2D tex=null;try{c.targetTexture=rt;c.Render();RenderTexture.active=rt;tex=new Texture2D(1600,1000,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1600,1000),0,0);tex.Apply();File.WriteAllBytes(O+name+".png",tex.EncodeToPNG());}finally{RenderTexture.active=prev;c.targetTexture=null;if(tex)UnityEngine.Object.DestroyImmediate(tex);UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(go);}}
 public static object Details(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved Edit required");var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform.Find("Remaining_Domes_Art");try{foreach(var spec in new[]{new[]{"W01","LivingAlcove"},new[]{"W03","UltrasoundCart"},new[]{"C03","TwinCoolingPump"},new[]{"N01","CentralVideoWall"},new[]{"E02","MealAssemblyIsland"},new[]{"E03","DeconShower"},new[]{"S01","TestControlConsole"}}){var t=root.Find(spec[0]).Cast<Transform>().First(x=>x.name.Contains(spec[1]));float d=spec[1]=="CentralVideoWall"?4.8f:spec[1]=="LivingAlcove"?3.1f:spec[1]=="UltrasoundCart"?1.5f:2.8f;var target=t.position+Vector3.up*(spec[1]=="CentralVideoWall"?1.7f:1.0f);Shot(spec[0]+"_detail",t.position+t.forward*d+t.right*.25f+Vector3.up*1.6f,target,70);}Shot("VL_front",new Vector3(44,-80.35f,23.5f),new Vector3(44,-80.35f,26.4f),88);}finally{EditorSceneManager.OpenScene(s.path);}return new{output=O,images=8};}
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved Edit required");var plan=JObject.Parse(File.ReadAllText(Repo+"/SourceAssets/B5_RemainingDomes/plan.json"));try{foreach(string code in plan["construction"].Values<string>()){var r=plan["rooms"][code];var o=new Vector3((float)r["x"],-82,-(float)r["v"]);int i=0;foreach(var door in r["doors"].Take(2)){float a=(float)door["angle"]*Mathf.Deg2Rad;var dir=new Vector3(Mathf.Cos(a),0,Mathf.Sin(a));Shot(code+"_"+i++,o+dir*((float)r["r"]-1.45f)+Vector3.up*1.65f,o-dir*2.0f+Vector3.up*1.75f,90);}}foreach(string code in new[]{"T08","T13","T19"}){var t=plan["tunnels"].Single(t=>(string)t["id"]=="B5-"+code);var p=new Vector3((float)t["p"][0],-80.35f,-(float)t["p"][1]);var q=new Vector3((float)t["q"][0],-80.35f,-(float)t["q"][1]);Shot(code,p+(q-p).normalized*2,q,78);}}finally{EditorSceneManager.OpenScene(s.path);}return new{output=O,images=27};}
}
